local _, addon = ...

addon.localeData.frFR.raceClassTexts = {Skyborne={DRUID={HELLO={ziel={"Le vent et la nature vous ont conduit jusqu'ici, %s. Bienvenue."},gruppe={"Le vent et la nature nous ont réunis. Bienvenue."}},WAVE={ziel={"Que le vent vous porte le salut de la nature, %s."},gruppe={"Que le vent vous porte à tous le salut de la nature."}},SALUTE={ziel={"Clairvoyance, équilibre et tout mon respect, %s."},gruppe={"Clairvoyance, équilibre et tout mon respect."}},BOW={ziel={"Je m'incline devant votre chemin, %s. Aucun arbre ne pousse sans ciel."},gruppe={"Aucun arbre ne pousse sans ciel. Tout mon respect."}},LAUGH={ziel={"Ha ! Même les feuilles tremblent de rire, %s."},gruppe={"Ha ! Même les feuilles tremblent de rire."}},DANCE={ziel={"Dansez avec moi, %s. Le vent fait bouger les feuilles, nous faisons le reste."},gruppe={"Le vent fait bouger les feuilles, nous faisons le reste."}},SIT={ziel={"Asseyez-vous, %s. Les racines ne poussent pas en plein vol."},gruppe={"Les racines ne poussent pas en plein vol. Reposons-nous."}},SLEEP={ziel={"Dormez bien, %s. Que le vent dans les branches veille sur vous."},gruppe={"Que le vent dans les branches veille sur nous."}},THANK={ziel={"Merci, %s. Que le vent et la nature vous rendent votre bonté."},gruppe={"Merci. Que le vent et la nature vous rendent votre bonté."}}}}}
